# shellcheck shell=bash
# The otel scenario: an OTLP collector in its own container, so that traces
# survive a replica being killed. It takes OTLP/gRPC over TLS from the lab CA
# and writes the spans to a file the e2e reads
# (.specs/ligo-test-environment.md, "The OTLP collector otel").

OTEL_PORT=4317
OTEL_TRACES=/var/lib/otelcol/traces.jsonl

# otel_config: the collector's configuration.
otel_config() {
	cat <<CFG
# lab: generated by test/lab/lab.sh (lib/otel.sh)
receivers:
  otlp:
    protocols:
      grpc:
        endpoint: 0.0.0.0:$OTEL_PORT
        tls:
          cert_file: /etc/otelcol/otel.crt
          key_file: /etc/otelcol/otel.key
exporters:
  file:
    path: $OTEL_TRACES
    flush_interval: 1s
service:
  pipelines:
    traces:
      receivers: [otlp]
      exporters: [file]
  telemetry:
    metrics:
      level: none
CFG
}

# otel_unit: the collector's systemd unit, as an unprivileged user.
otel_unit() {
	cat <<UNIT
[Unit]
Description=OpenTelemetry Collector (lab)
After=network-online.target

[Service]
User=otelcol
StateDirectory=otelcol
ExecStart=/usr/local/bin/otelcol-contrib --config=/etc/otelcol/config.yaml
Restart=on-failure
RestartSec=2

[Install]
WantedBy=multi-user.target
UNIT
}

# otel_up: the container otel with the pinned collector, verified against its
# checksum, its certificate, configuration and unit.
otel_up() {
	section "OTLP collector"
	inner_container otel "$LAB_OTEL_MEMORY"
	pki_issue otel "DNS:otel.ligo.lab,IP:$(inner_ip otel)"
	local version="$LAB_OTEL_VERSION" file tar dir
	if [[ "$(inner_exec otel /usr/local/bin/otelcol-contrib --version 2>/dev/null)" != *" $version"* ]]; then
		file="otelcol-contrib_${version}_linux_amd64.tar.gz"
		tar="$(fetch "https://github.com/open-telemetry/opentelemetry-collector-releases/releases/download/v$version/$file" "$LAB_OTEL_SHA256")"
		dir="$(mktemp -d)"
		tar -xzf "$tar" -C "$dir" otelcol-contrib || die "otel: cannot unpack $file"
		inner_push "$dir/otelcol-contrib" otel /usr/local/bin/otelcol-contrib 0755
		rm -rf "$dir"
	fi
	inner_exec otel sh -c 'id otelcol >/dev/null 2>&1 || useradd --system --no-create-home otelcol; install -d -o root -g otelcol -m 0750 /etc/otelcol'
	inner_push "$LAB_STATE_DIR/pki/otel.crt" otel /etc/otelcol/otel.crt 0644
	inner_push "$LAB_STATE_DIR/pki/otel.key" otel /etc/otelcol/otel.key 0640
	inner_exec otel chgrp otelcol /etc/otelcol/otel.key
	otel_config | inner_exec otel sh -c 'cat >/etc/otelcol/config.yaml'
	otel_unit | inner_exec otel sh -c 'cat >/etc/systemd/system/otelcol.service'
	inner_exec otel sh -c 'systemctl daemon-reload; systemctl enable otelcol >/dev/null 2>&1; systemctl restart otelcol'
	sleep 2
	inner_exec otel systemctl is-active --quiet otelcol || die "otel: the collector does not run: lab.sh logs otel otelcol"
	env_set .otel "$(jq -n --arg ip "$(inner_ip otel)" --arg version "$version" '{address: $ip, version: $version}')"
	info "otel: collector $version takes OTLP/gRPC with TLS on otel.ligo.lab:$OTEL_PORT"
}

# serve_test_otel: traces end to end (10.1b, §10.1): a request with a sampled
# traceparent through one replica, its approval through the other, a binding
# applied, a second one that fails at the target; then the collector's file,
# read by the test on ligo1.
serve_test_otel() {
	inner_exists otel || die "serve test-otel needs the collector: lab.sh up --scenario otel"
	inner_exec ligo1 grep -q otlp_endpoint /etc/ligo/server.yaml || die "ligo has no collector configured: lab.sh serve install"
	deploy_tests
	section "Traces of ligo serve"
	local other rc=0
	other="$(ligo_hosts | tail -1)"
	E2E_SUFFIX="$(openssl rand -hex 4)"
	E2E_TRACE="$(openssl rand -hex 16)"
	serve_admins
	serve_e2e '^TestServeE2EApply$' ligo1 "$other" || die "TestServeE2EApply failed"
	# EnsureTarget's GRANT fails while the role has another name
	pg_superuser -d "$SERVE_DB" -c 'ALTER ROLE "LEDGER_RO_ROLE" RENAME TO "LEDGER_RO_ROLE_AWAY"' >/dev/null
	serve_e2e '^TestServeTraceFailed$' ligo1 "$other" || rc=$?
	pg_superuser -d "$SERVE_DB" -c 'ALTER ROLE "LEDGER_RO_ROLE_AWAY" RENAME TO "LEDGER_RO_ROLE"' >/dev/null
	((rc == 0)) || die "TestServeTraceFailed failed"
	sleep 10 # the SDK exports every 5s, the collector's file flushes every 1s
	inner_exec otel cat "$OTEL_TRACES" | inner_exec ligo1 sh -c "cat >'$LIGO1_E2E/traces.jsonl' && chmod 0644 '$LIGO1_E2E/traces.jsonl'"
	serve_e2e '^TestServeTraceFile$' ligo1 "$other" || die "TestServeTraceFile failed"
	info "traces reach the collector over TLS from $(ligo_hosts | xargs), in the caller's trace, without secrets or error text"
}
